// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing, Img } from '../remotionShim';
// User Uploaded Assets
const TONGUE_IMG_URL = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/ab92ab7c97ce44dda96504e941e3d2f6.png";
const STOMACH_IMG_URL = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/ca1b01be2c2741af9eab8e8c1856b846.png";



export type MedicalDiagramProps = Record<string, any>;

const MedicalDiagram: React.FC<MedicalDiagramProps> = ({
  backgroundColor = "#FAFAFA",
  transparentBackground = false,
  durationInSeconds = 5,
  highlightColor = "#5C9E9F", // Muted teal glow
  lineColor = "#A3B1B8",
  nodeCount = 5,
  nodeSize = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Scaling & Positioning - Optimized for 9:16 vertical
  const s = Math.min(width, height);
  
  // Organ Sizes
  const tongueSize = s * 0.35; 
  const stomachSize = s * 0.5;

  // Layout Placement: Tongue Top-Left, Stomach Bottom-Right
  const tongueX = width * 0.25;
  const tongueY = height * 0.25;
  const stomachX = width * 0.75;
  const stomachY = height * 0.72;

  // Define the bezier curve connecting the two organs
  const p0 = { x: tongueX, y: tongueY };
  const p1 = { x: tongueX, y: tongueY + height * 0.2 };
  const p2 = { x: stomachX, y: stomachY - height * 0.2 };
  const p3 = { x: stomachX, y: stomachY };
  const connectionPath = `M ${p0.x} ${p0.y} C ${p1.x} ${p1.y}, ${p2.x} ${p2.y}, ${p3.x} ${p3.y}`;

  // --- Animation Timeline ---
  
  // 1. Tongue appears (Frames 5 - 25)
  const tongueScale = spring({ fps, frame: Math.max(0, frame - 5), config: { damping: 14 } });

  // 2. Dotted Line Travels (Frames 30 - 75)
  // We use a mask with a strokeDashoffset to reveal the dotted line organically
  const pathLength = 2500; // Overestimated safe length for the bezier path
  const lineRevealOffset = interpolate(frame, [30, 75], [pathLength, 0], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.quad)
  });
  // The dotted line slowly crawls as well for the "animated line" effect
  const lineDashCrawl = -frame * 1.5;

  // 3. Stomach appears as line arrives (Frames 65 - 85)
  const stomachScale = spring({ fps, frame: Math.max(0, frame - 65), config: { damping: 14 } });

  // 4. Constant Soft Glow for hold state (Fades in Frames 85 - 105)
  const holdGlowOpacity = interpolate(frame, [85, 105], [0, 0.4], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const subtlePulse = Math.sin(frame * 0.05) * 0.1;
  const finalGlowOpacity = holdGlowOpacity * (1 + subtlePulse);

  // Generate deterministic pseudo-random positions for the glowing nodes on the organs
  const nodes = Array.from({ length: nodeCount }).map((_, i) => {
    // Tongue Node Offset (placed around the tastebuds)
    const tAngle = i * (Math.PI * 2 / nodeCount) + (i % 2) * 0.5;
    const tRadius = (0.15 + (i % 3) * 0.1) * (tongueSize / 2);
    const tx = Math.cos(tAngle) * tRadius;
    const ty = Math.sin(tAngle) * tRadius;

    // Stomach Node Offset (placed along the main body)
    const sAngle = i * (Math.PI * 2 / nodeCount) - (i % 2) * 0.3;
    const sRadius = (0.2 + (i % 3) * 0.15) * (stomachSize / 2);
    const sx = Math.cos(sAngle) * sRadius;
    const sy = Math.sin(sAngle) * sRadius;

    return { id: i, tx, ty, sx, sy };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <svg width="100%" height="100%" style={{ position: "absolute", top: 0, left: 0 }}>
        <defs>
          {/* Mask to progressively reveal the connection line */}
          <mask id="line-reveal-mask">
            <path
              d={connectionPath}
              fill="none"
              stroke="#FFFFFF"
              strokeWidth="40" // Thick enough to fully cover the dashed line
              strokeDasharray={pathLength}
              strokeDashoffset={lineRevealOffset}
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
          </mask>

          {/* Soft Radial Glow for the Hold State */}
          <radialGradient id="organGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor={highlightColor} stopOpacity="1" />
            <stop offset="50%" stopColor={highlightColor} stopOpacity="0.4" />
            <stop offset="100%" stopColor={highlightColor} stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Traveling Dotted Connection Line */}
        <path
          d={connectionPath}
          fill="none"
          stroke={lineColor}
          strokeWidth={5}
          strokeDasharray="10 16"
          strokeDashoffset={lineDashCrawl}
          strokeLinecap="round"
          mask="url(#line-reveal-mask)"
          style={{ transition: "none", opacity: 0.8 }}
        />

        {/* --- LEFT: Tongue Group --- */}
        <g style={{ transform: `translate(${tongueX}px, ${tongueY}px) scale(${tongueScale})`, transition: "none" }}>
          {/* Glowing Aura */}
          <circle r={tongueSize * 0.6} fill="url(#organGlow)" opacity={finalGlowOpacity} style={{ transition: "none" }} />
          
          {/* Tongue Illustration */}
          <foreignObject x={-tongueSize / 2} y={-tongueSize / 2} width={tongueSize} height={tongueSize}>
            <Img src={TONGUE_IMG_URL} style={{ width: "100%", height: "100%", objectFit: "contain", transition: "none" }} />
          </foreignObject>

          {/* Tongue Pulsing Nodes (Activation Ripple) */}
          {nodes.map((node, i) => {
            const startFrame = 15 + i * 4;
            const pScale = interpolate(frame, [startFrame, startFrame + 25], [1, 2.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const pOpacity = interpolate(frame, [startFrame, startFrame + 25], [0.8, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const isVisible = frame >= startFrame;

            return (
              <g key={`t-${node.id}`} style={{ transform: `translate(${node.tx}px, ${node.ty}px)`, transition: "none" }}>
                <circle r={nodeSize * 0.8} fill={highlightColor} opacity={isVisible ? 1 : 0} style={{ transition: "none" }} />
                <circle r={nodeSize * 0.8} fill={highlightColor} style={{ transform: `scale(${pScale})`, opacity: pOpacity, transition: "none" }} />
              </g>
            );
          })}
        </g>

        {/* --- RIGHT: Stomach Group --- */}
        <g style={{ transform: `translate(${stomachX}px, ${stomachY}px) scale(${stomachScale})`, transition: "none" }}>
          {/* Glowing Aura */}
          <circle r={stomachSize * 0.55} fill="url(#organGlow)" opacity={finalGlowOpacity} style={{ transition: "none" }} />
          
          {/* Stomach Illustration */}
          <foreignObject x={-stomachSize / 2} y={-stomachSize / 2} width={stomachSize} height={stomachSize}>
            <Img src={STOMACH_IMG_URL} style={{ width: "100%", height: "100%", objectFit: "contain", transition: "none" }} />
          </foreignObject>

          {/* Stomach Pulsing Nodes (Arrival Ripple) */}
          {nodes.map((node, i) => {
            const startFrame = 75 + i * 4;
            const pScale = interpolate(frame, [startFrame, startFrame + 25], [1, 2.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const pOpacity = interpolate(frame, [startFrame, startFrame + 25], [0.8, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
            const isVisible = frame >= startFrame;

            return (
              <g key={`s-${node.id}`} style={{ transform: `translate(${node.sx}px, ${node.sy}px)`, transition: "none" }}>
                <circle r={nodeSize * 0.8} fill={highlightColor} opacity={isVisible ? 1 : 0} style={{ transition: "none" }} />
                <circle r={nodeSize * 0.8} fill={highlightColor} style={{ transform: `scale(${pScale})`, opacity: pOpacity, transition: "none" }} />
              </g>
            );
          })}
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default MedicalDiagram;